    def task(doc, number, title, actions, code, cases, notes=None):
        # Explicit paragraph breaks separate independently numbered requirements.
        actions = [point.strip() for action in actions for point in action.split('\n\n') if point.strip()]
        statement = '\n\n'.join(f'{i}. {line}' for i, line in enumerate(actions, 1))
        add(doc, number, title, statement, '', '', code, cases, notes=notes)
        ex = exercises[key(doc, number)]
        for test in ex['tests']:
            if not test['is_hidden']:
                test.update(ns['example_session'](solutions[key(doc, number)], test))
        ex['content']['blocks'] = ns['statement_blocks'](ex)

